import medusaPlugin from "@medusa/eslint-plugin";
import tsParser from "@typescript-eslint/parser";

export default [
	{
		ignores: [
			"**/node_modules/**",
			"**/dist/**",
			"**/coverage/**",
			"**/.turbo/**",
			// Generated by Expo from app.config.ts; never edited by hand.
			"apps/native/ios/**",
			"apps/native/android/**",
			"apps/native/.expo/**",
		],
	},
	{
		files: ["**/*.{ts,tsx}"],
		languageOptions: {
			parser: tsParser,
		},
		rules: {
			// A name says what a value is. `t` is the translation function by
			// convention, `_` marks a value that is deliberately unused.
			"id-length": ["error", { min: 2, exceptions: ["t", "_"] }],
		},
	},
	{
		files: ["apps/*/src/**/*.{ts,tsx}"],
		...medusaPlugin.configs.recommended,
	},
	{
		// A colour is a role from `@/shared/theme`; its value lives only in
		// `palette.json`, which ESLint does not read, so a theme change is a
		// change in one file.
		files: ["apps/native/**/*.{ts,tsx,js}"],
		rules: {
			"no-restricted-syntax": [
				"error",
				{
					selector: "Literal[value=/^#([0-9a-fA-F]{3,4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$/]",
					message:
						"Colour values live in src/shared/theme/lib/palette.json. Use a role from @/shared/theme.",
				},
				{
					selector: "Literal[value=/^rgba?\\(/i]",
					message:
						"Colour values live in src/shared/theme/lib/palette.json. Use a role from @/shared/theme.",
				},
			],
		},
	},
	{
		files: ["packages/*/src/**/*.{ts,tsx}"],
		plugins: { "@medusa": medusaPlugin },
		rules: {
			"@medusa/kebab-case-folders": "error",
			"@medusa/folder-structure": "error",
		},
	},
];
